@startuml
class FurnitureLine {
  +name : string
}

class Furniture {
  +type : string
  +reference : string
  +sellingPrice : double
}

class ComponentType {
  +code : int
  +manufacturingPrice : double
  +type : string
}

class Component {
  +code : int
}

class Store {
  +address : string
  +faxNumber : string
}

class Order {
  +orderNumber : string
  +date : date
}

class OrderLine {
  +quantity : int
}

FurnitureLine "1" *-- "*" Furniture : consists of
Furniture "1" *-- "*" Component : is composed of
ComponentType "1" -- "*" Component : is a type of
Component "1" -- "*" Component : can be used more than once
Store "1" -- "*" Order : places
Order "1" *-- "1..*" OrderLine : contains
OrderLine "*" -- "1" Furniture : orders
OrderLine "*" -- "1" Store : placed at
@enduml

